package io.vibeminer.desktop;

import io.vibeminer.application.bootstrap.*;
import io.vibeminer.domain.*;
import org.junit.jupiter.api.Test;
import java.time.Instant;
import java.util.*;
import java.util.concurrent.*;
import static org.junit.jupiter.api.Assertions.*;

class InstallPresentationModelTest {
    static BuildSnapshot build(String version){return new BuildSnapshot("wowt","Retail","PTR","us",version,"a".repeat(31)+(version.equals("A")?"1":"2"),"b".repeat(32),Instant.EPOCH,true);}
    static InstallPlan plan(BuildSnapshot build){return new InstallPlan(build,new SourceDocument("https://fixture.example/config",Instant.EPOCH,"config".getBytes(java.nio.charset.StandardCharsets.UTF_8)),"c".repeat(32),"d".repeat(32),120,90);}
    static InstallInspection inspection(BuildSnapshot b){var windows=new InstallInspection.Tag("Windows",1);var locale=new InstallInspection.Tag("enUS",3);return new InstallInspection(plan(b),new StoredObject(new ObjectDigest("e".repeat(64)),90),new SourceVerificationEvidence("fixture-verifier-v1","https://original.example/list",Instant.EPOCH),List.of(new InstallInspection.Entry("Client.exe","f".repeat(32),500,List.of(windows)),new InstallInspection.Entry("Data/strings.bin","1".repeat(32),200,List.of(locale))),List.of(windows,locale));}
    static final class Fake implements BootstrapService {
        CompletableFuture<InstallPlan> checking=new CompletableFuture<>();CompletableFuture<InstallInspection> downloading=new CompletableFuture<>(),reopening=new CompletableFuture<>();
        int checks,downloads,reopens;InstallPlan requested;BuildSnapshot reopened;
        public CompletionStage<InstallPlan> inspectConfiguration(BuildSnapshot b){checks++;return checking;}
        public CompletionStage<InstallInspection> download(InstallPlan p){downloads++;requested=p;return downloading;}
        public CompletionStage<InstallInspection> reopen(BuildSnapshot b){reopens++;reopened=b;return reopening;}
        public void close(){throw new AssertionError("A view must not close the shared service");}
    }
    @Test void selectionDoesNotAutomaticallyCheckOrDownload(){var f=new Fake();var m=new InstallPresentationModel(f,Runnable::run,s->{});m.selectBuild(build("A"));assertEquals(0,f.checks+f.downloads+f.reopens);assertEquals(InstallPresentationModel.Stage.UNCHECKED,m.state().stage());}
    @Test void configurationCheckOnlyProducesImmutableCostPlan(){var f=new Fake();var m=new InstallPresentationModel(f,Runnable::run,s->{});var b=build("A");m.selectBuild(b);m.check();assertTrue(m.state().busy());assertEquals(1,f.checks);assertEquals(0,f.downloads);f.checking.complete(plan(b));assertEquals(InstallPresentationModel.Stage.PLANNED,m.state().stage());assertEquals(90,m.state().plan().encodedBytes());assertEquals(120,m.state().plan().decodedBytes());assertNull(m.state().inspection());}
    @Test void downloadRequiresCheckedExactPlanAndDoesNotFollowLatest(){var f=new Fake();var m=new InstallPresentationModel(f,Runnable::run,s->{});var b=build("A");m.selectBuild(b);m.download();assertEquals(0,f.downloads);m.check();f.checking.complete(plan(b));m.download();assertEquals(plan(b),f.requested);assertEquals(1,f.downloads);f.downloading.complete(inspection(b));assertEquals(InstallPresentationModel.Stage.RETAINED,m.state().stage());assertEquals("https://original.example/list",m.state().inspection().verification().sourceUrl());}
    @Test void cancelDetachesConsumerAndOpensNoUnverifiedList(){var f=new Fake();var m=new InstallPresentationModel(f,Runnable::run,s->{});m.selectBuild(build("A"));m.check();m.cancel();assertTrue(f.checking.isCancelled());assertEquals(InstallPresentationModel.Stage.CANCELLED,m.state().stage());assertNull(m.state().inspection());assertFalse(m.state().busy());}
    @Test void switchedExactBuildRejectsLateAlreadyCommittedResponse(){var f=new Fake();f.checking=new CompletableFuture<>(){@Override public boolean cancel(boolean interrupt){return false;}};var m=new InstallPresentationModel(f,Runnable::run,s->{});m.selectBuild(build("A"));m.check();var old=f.checking;m.selectBuild(build("B"));old.complete(plan(build("A")));assertEquals(build("B"),m.state().build());assertEquals(InstallPresentationModel.Stage.UNCHECKED,m.state().stage());assertNull(m.state().plan());}
    @Test void responseFromDifferentSourceCannotPaintEvenWithoutSwitch(){var f=new Fake();var m=new InstallPresentationModel(f,Runnable::run,s->{});m.selectBuild(build("A"));m.check();f.checking.complete(plan(build("B")));assertEquals(InstallPresentationModel.Stage.FAILED,m.state().stage());assertNull(m.state().plan());assertNull(m.state().inspection());}
    @Test void offlineReopenDoesNotInspectConfigurationOrDownload(){var f=new Fake();var m=new InstallPresentationModel(f,Runnable::run,s->{});var b=build("A");m.selectBuild(b);m.reopen();assertEquals(1,f.reopens);assertEquals(b,f.reopened);assertEquals(0,f.checks+f.downloads);f.reopening.complete(inspection(b));assertEquals(InstallPresentationModel.Stage.RETAINED,m.state().stage());}
    @Test void missingOfflineListDoesNotSilentlyFetch(){var f=new Fake();var m=new InstallPresentationModel(f,Runnable::run,s->{});m.selectBuild(build("A"));m.reopen();f.reopening.completeExceptionally(new CompletionException(new BootstrapException(BootstrapException.Reason.MISSING_LOCAL,"private path")));assertEquals(BootstrapException.Reason.MISSING_LOCAL,m.state().reason());assertEquals(0,f.checks+f.downloads);assertFalse(m.state().message().contains("private path"));}
    @Test void typedFailureReasonSurvivesItsTransportCause(){var f=new Fake();var m=new InstallPresentationModel(f,Runnable::run,s->{});m.selectBuild(build("A"));m.reopen();f.reopening.completeExceptionally(new CompletionException(new BootstrapException(BootstrapException.Reason.INTEGRITY,"not for display",new java.io.IOException("internal"))));assertEquals(BootstrapException.Reason.INTEGRITY,m.state().reason());assertTrue(m.state().message().contains("verification"));}
    @Test void downloadedResponseMustMatchConsentedPlanCostAndKeys(){var f=new Fake();var m=new InstallPresentationModel(f,Runnable::run,s->{});var b=build("A");m.selectBuild(b);m.check();f.checking.complete(plan(b));m.download();var original=inspection(b);var changed=new InstallPlan(b,plan(b).configuration(),"2".repeat(32),"3".repeat(32),121,91);f.downloading.complete(new InstallInspection(changed,original.object(),original.verification(),original.entries(),original.tags()));assertEquals(InstallPresentationModel.Stage.FAILED,m.state().stage());assertNull(m.state().inspection());}
    @Test void failedOfflineRecheckCannotKeepClaimingRetainedContent(){
        for(var reason:List.of(BootstrapException.Reason.MISSING_LOCAL,BootstrapException.Reason.INTEGRITY)){
            var f=new Fake();var m=new InstallPresentationModel(f,Runnable::run,s->{});var b=build("A");m.selectBuild(b);m.reopen();f.reopening.complete(inspection(b));assertNotNull(m.state().inspection());
            f.reopening=new CompletableFuture<>();m.reopen();f.reopening.completeExceptionally(new BootstrapException(reason,"internal"));assertNull(m.state().inspection());assertEquals(reason,m.state().reason());
        }
    }
    @Test void failedDownloadKeepsPlanForExplicitRetry(){var f=new Fake();var m=new InstallPresentationModel(f,Runnable::run,s->{});var b=build("A");m.selectBuild(b);m.check();f.checking.complete(plan(b));m.download();f.downloading.completeExceptionally(new BootstrapException(BootstrapException.Reason.INTEGRITY,"raw"));assertEquals(plan(b),m.state().plan());assertNull(m.state().inspection());assertEquals(BootstrapException.Reason.INTEGRITY,m.state().reason());}
    @Test void duplicateClickCannotQueueSecondConsumer(){var f=new Fake();var m=new InstallPresentationModel(f,Runnable::run,s->{});m.selectBuild(build("A"));m.check();m.check();m.reopen();assertEquals(1,f.checks);assertEquals(0,f.reopens);}
    @Test void filteringNamesAndTagsPreservesVerifiedEntriesAndEvidence(){var f=new Fake();var m=new InstallPresentationModel(f,Runnable::run,s->{});var b=build("A");m.selectBuild(b);m.reopen();var verified=inspection(b);f.reopening.complete(verified);assertEquals("Client.exe",m.matching("WINDOWS").getFirst().name());assertEquals("Data/strings.bin",m.matching("strings").getFirst().name());assertTrue(m.matching("missing").isEmpty());assertSame(verified,m.state().inspection());}
    @Test void clearingBuildCancelsAndClearsPriorScope(){var f=new Fake();var m=new InstallPresentationModel(f,Runnable::run,s->{});m.selectBuild(build("A"));m.check();m.selectBuild(null);assertTrue(f.checking.isCancelled());assertEquals(InstallPresentationModel.Stage.NO_BUILD,m.state().stage());assertNull(m.state().inspection());}
    @Test void callbacksUseUiExecutorAndClosedModelIgnoresResults(){var f=new Fake();Queue<Runnable> ui=new ArrayDeque<>();var m=new InstallPresentationModel(f,ui::add,s->{});m.selectBuild(build("A"));m.check();f.checking.complete(plan(build("A")));assertTrue(m.state().busy());m.close();ui.remove().run();assertNull(m.state().plan());}
}
